CREATE FUNCTION public.validate_piece_medium() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.medium_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.taxonomy WHERE id=NEW.medium_id AND kind='medium' AND status='active') THEN RAISE EXCEPTION 'Choose a valid medium'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_piece_medium BEFORE INSERT OR UPDATE OF medium_id ON public.pieces FOR EACH ROW EXECUTE FUNCTION public.validate_piece_medium();
CREATE FUNCTION public.save_piece_specialties(target_piece text,specialty_ids text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.pieces; u uuid:=auth.uid(); BEGIN IF u IS NULL OR NOT public.has_role(u,'artist') THEN RAISE EXCEPTION 'Artist account required'; END IF; SELECT * INTO p FROM public.pieces WHERE id=target_piece AND artist=u FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION 'Piece not found'; END IF; IF EXISTS(SELECT 1 FROM unnest(specialty_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.taxonomy WHERE id=x AND kind='specialty' AND status='active' AND parent_id=p.medium_id)) THEN RAISE EXCEPTION 'Specialties must match this piece'; END IF; DELETE FROM public.piece_specialties WHERE piece_id=target_piece; INSERT INTO public.piece_specialties SELECT target_piece,x FROM (SELECT DISTINCT unnest(specialty_ids) x) s; END $$;
REVOKE ALL ON FUNCTION public.save_piece_specialties(text,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_piece_specialties(text,text[]) TO authenticated;